CREATE POLICY "Studio files require staff even alongside public media policy" ON storage.objects AS RESTRICTIVE FOR SELECT TO anon,authenticated USING (bucket_id <> 'media' OR COALESCE((storage.foldername(name))[1], '') <> 'studio' OR public.is_staff(auth.uid())); CREATE INDEX studio_projects_brand_updated_idx ON public.studio_projects (brand_id,updated_at DESC); CREATE INDEX studio_assets_brand_created_idx ON public.studio_assets (brand_id,created_at DESC); ALTER TABLE public.studio_projects ALTER COLUMN created_by SET DEFAULT auth.uid(); ALTER TABLE public.studio_assets ALTER COLUMN created_by SET DEFAULT auth.uid();